import Foundation

/// The Ukrainian passages.
///
/// Written rather than translated: about sixty of the English passages
/// are etymologies of English words and are simply false in any other
/// language, so this bank comes from its own word histories, its own
/// literature and its own proverbs.
extension Quotes {
    static let ukrainian: [Passage] = [
        // MARK: - Beginnings

        // MARK: The first act
        Passage(text: "Проклюнутися кажуть і про насінину, і про пуп'янок, і про пташеня в яйці: щось уперше пробило те, що його доти тримало.", source: "Українська мова", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Корінець виходить із насінини раніше за пагін: рослина спершу шукає воду, а вже потім світло.", source: "Ботаніка", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Енеїда Івана Котляревського, надрукована 1798 року, стала першою книжкою, писаною живою розмовною українською мовою.", source: "Історія літератури", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Перша книжка, надрукована на українських землях, — львівський Апостол 1574 року; складали її з литих літер, а не різали дошками.", source: "Історія книги", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Світає — дієслово без підмета. Ніхто не світає; воно просто починається, і мова не питає, хто це робить.", source: "Українська мова", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Первоцвіт — назва для того, що зацвітає найпершим, ще коли в затінку під кущами лежить сніг.", source: "Ботаніка", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Зажинки — перший день жнив. Перший сніп жали окремо і несли додому, бо з нього починалося все інше.", source: "Народний звичай", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Брунька, яка розкрилася навесні, була закладена ще торік улітку: дерево готує свій початок за рік наперед.", source: "Ботаніка", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Першу ватру на полонині розпалювали живим вогнем — тертям дерева об дерево, — і від неї потім горіло ціле літо.", source: "Гуцульський звичай", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Трипільці ставили нову хату на місці старої і починали те саме село наново кожні шістдесят чи вісімдесят років.", source: "Археологія", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Почин — старе слово не для наміру і не для плану, а для першої зробленої дії, з якої вже щось вийшло.", source: "Українська мова", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Ластівка починає гніздо з однієї грудочки болота, приліпленої до стіни; на ціле гніздо їх треба близько тисячі.", source: "Орнітологія", theme: .beginnings, subtheme: .theFirstAct),

        // MARK: Small to large
        Passage(text: "З малої іскри великий вогонь.", source: "Українське прислів'я", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Мала крапля і камінь довбає.", source: "Українське прислів'я", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Мала праця краща за велике безділля.", source: "Українське прислів'я", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Зерно до зерна — буде мірка.", source: "Українське прислів'я", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Жолудь важить кілька грамів. Дуб, що з нього виросте, за триста років набере понад двадцять тонн, і майже все це — з повітря та води.", source: "Ботаніка", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Одна бджола за все своє життя зносить меду менше, ніж уміститься в чайній ложці; вулик за літо набирає його десятками кілограмів.", source: "Бджільництво", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Насінина орхідеї легша за порошинку і не має жодного запасу їжі: рости вона починає тільки в спілці з грибом.", source: "Ботаніка", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Петро Прокопович улаштував 1814 року вулик із рухомими рамками, і відтоді мед можна брати, не розоряючи рою.", source: "Бджільництво", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Трипільські Тальянки виросли з кількох хат у поселення на кількасот гектарів — одне з найбільших у тодішній Європі.", source: "Археологія", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Гриб, який видно в лісі, — то лише плід. Сама грибниця під ногами тягнеться на гектари і може жити століттями.", source: "Мікологія", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Кожна сніжинка легша за перо, а разом вони ламають гілляки.", source: "Фізика", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Мурашник починається з однієї самиці, яка скинула крила і закопалася в землю; далі все робить вона сама, поки не вийде перший десяток робітниць.", source: "Ентомологія", theme: .beginnings, subtheme: .smallToLarge),

        // MARK: What a start settles
        Passage(text: "Що посієш, те й пожнеш.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Добрий початок — половина діла.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Як дбаєш, так і маєш.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Посієш вчасно — збереш рясно.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Не святі горшки ліплять.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Яке коріння, таке й насіння.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Хто рано встає, тому Бог дає.", source: "Українське прислів'я", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Глибина, на яку лягла насінина, вирішена раз назавжди: закладеш глибше — і сходи вийдуть пізніше або не вийдуть зовсім.", source: "Хліборобство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Перший вінець зрубу кладуть на дубові підвалини, і все, що стане вище, стоятиме рівно настільки, наскільки рівний він.", source: "Теслярство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Сорт майбутнього дерева вирішує не корінь, а маленький живець, приставлений до зрізу навесні.", source: "Садівництво", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Пантелеймон Куліш склав правопис, у якому слова писалися так, як їх чути; теперішній український правопис виріс саме з нього.", source: "Мовознавство", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Першу борозну орач веде, дивлячись на щось далеке й непорушне; за нею потім вирівнюють усі решта.", source: "Хліборобство", theme: .beginnings, subtheme: .whatAStartSettles),

        // MARK: - Waiting

        // MARK: Held back
        Passage(text: "Стан спокою — так ботаніки називають те, що робить насінина, коли ще не проростає, хоча все для цього вже є.", source: "Ботаніка", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Озимина сходить восени, лягає під сніг і колоситься аж улітку: без зими вона колоса не викине.", source: "Хліборобство", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Стратифікація: насіння багатьох дерев не зійде, поки не пролежить у холоді стільки, скільки триває справжня зима.", source: "Ботаніка", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Тверда лушпина в насінини дикої вики не пускає до себе воду доти, доки її не потріскає мороз або не перетравить тварина.", source: "Ботаніка", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Переліг — поле, яке зумисне лишили відпочивати. Воно не порожнє, воно чекає.", source: "Хліборобство", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Ждати з моря погоди.", source: "Українське прислів'я", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Бджоли взимку не сплять: вони збиваються в клуб, усю зиму гріють одна одну і чекають першого теплого дня, щоб вилетіти.", source: "Бджільництво", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Терпи, козаче, отаманом будеш.", source: "Українське прислів'я", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Цибулина тюльпана закладає квітку ще восени і чекає під землею всю зиму з готовою квіткою всередині.", source: "Ботаніка", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Гусениця в коконі не спить і не росте: вона перебудовується, і поки це триває, її не можна ні поквапити, ні розкрити.", source: "Ентомологія", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Дозріти означає не побільшати, а дійти: яблуко на гілці останні тижні вже не росте, воно доходить.", source: "Українська мова", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Тісто під рушником не любить, щоб його чіпали. Поки воно підходить, від господині не залежить нічого.", source: "Куховарство", theme: .waiting, subtheme: .heldBack),

        // MARK: The long count
        Passage(text: "Чорнозем наростає десь на сантиметр за століття; метр такої землі старший за всі міста, що на ній стоять.", source: "Ґрунтознавство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Оптимістична печера на Тернопільщині — найдовша гіпсова печера світу; її ходи разом перевищують двісті п'ятдесят кілометрів, і вода точила їх мільйони років.", source: "Геологія", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Дуб починає родити жолуді щойно десь на сороковому році і після того може стояти ще шістсот.", source: "Лісівництво", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Бурштин — смола, яка чекала десятки мільйонів років, щоб стати каменем, і зберегла все, що в неї встигло влипнути.", source: "Геологія", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "У лісі в зозулі питали, скільки років жити, і лічили, доки вона кує. Вона майже завжди кувала довго.", source: "Народний звичай", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Лелеки вертаються до того самого гнізда десятиліттями, надбудовуючи його щороку; старе гніздо може важити майже тонну.", source: "Орнітологія", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Асканія-Нова береже ділянку степу, якої не орав ніхто й ніколи; зораний степ не робиться степом назад навіть за сто років.", source: "Заповідна справа", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Липа зацвітає щойно років на двадцятому, і той, хто її саджає, рідко бачить перший мед із неї.", source: "Бджільництво", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Свіжий сир робиться за ніч, а бринза на полонині доходить тижнями, і вівчар знає це наперед.", source: "Полонинське господарство", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Горіх садять для онуків: перші горіхи він дасть років через десять, а рясно родитиме, коли той, хто садив, уже посивіє.", source: "Садівництво", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Сорок днів після Великодня, сорок мучеників, сорок клинців на писанці: сорок у мові означає не так число, як довгий рахунок.", source: "Народний календар", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Ковила цвіте не щороку, і в суху весну степ може цілий рік простояти без жодної сивої китиці.", source: "Ботаніка", theme: .waiting, subtheme: .theLongCount),

        // MARK: Standing and watching
        Passage(text: "Стояла я і слухала весну, весна мені багато говорила.", source: "Леся Українка", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Мені тринадцятий минало. Я пас ягнята за селом.", source: "Тарас Шевченко, Кобзар", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Серед дійових осіб у Коцюбинського в Intermezzo названо ниви у червні, сонце, зозулю і жайворонків.", source: "Михайло Коцюбинський", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "У зграї журавлів той, хто стоїть на варті, не годується; поки решта їсть, він дивиться, а потім вони міняються.", source: "Орнітологія", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Пасічник улітку сидить біля вуликів і слухає: рій, який збирається виходити, чути раніше, ніж видно.", source: "Бджільництво", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Погоду вгадували не приладом, а тим, як лягає роса, куди йде дим із комина і чи літає в повітрі павутиння.", source: "Народна прикмета", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Вівчар на полонині може за цілий день не сказати нікому й слова, але вівці знають, де він стоїть.", source: "Полонинське господарство", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Хто жде, той діждеться.", source: "Українське прислів'я", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Над водою час іде інакше: рибалка сидить від світання і каже, що тільки-но прийшов.", source: "Спостереження", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Соняшник повертає голову за сонцем, поки росте; коли зацвів — стає на схід і більше не крутиться.", source: "Ботаніка", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Суха ялинова гілка на стіні опускається перед дощем і підіймається на погоду; це найдешевший барометр, який буває.", source: "Народна прикмета", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Дивитися і глядіти — не те саме: глядіти дитину означає не тільки бачити її, а й відповідати за неї.", source: "Українська мова", theme: .waiting, subtheme: .standingAndWatching),

        // MARK: - Renewal

        // MARK: Cut and come again
        Passage(text: "Отава — трава, яка відросла на скошеному лузі. Друга за літо, і часто солодша за першу.", source: "Хліборобство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Верба, зрізана на кіл і встромлена в мокру землю, пускає коріння; тому в тину інколи виростає ціле дерево.", source: "Ботаніка", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Де верба, там і вода.", source: "Українське прислів'я", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Виноградну лозу щороку ріжуть майже до пенька, і саме через це вона родить.", source: "Виноградарство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Лозу на кошики беруть із пенька, який ріжуть щозими вже сто років поспіль; що частіше ріжуть, то рівніші прути.", source: "Лозоплетіння", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Живець — гілочка, зрізана з дерева, яку садять окремо і з якої виростає те саме дерево ще раз.", source: "Садівництво", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Ящірка, схоплена за хвіст, лишає хвіст і йде далі; новий виросте, тільки вже без кістки.", source: "Зоологія", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Спориш на стежці топчуть цілісіньке літо, і саме тому він там росте: витоптаний він тримається краще, ніж некошений.", source: "Ботаніка", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Коли мороз поб'є цвіт, дерево викидає другий. Урожай буде менший, але буде.", source: "Садівництво", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Скошений полин пахне сильніше, ніж нескошений, і чути його аж від дороги.", source: "Ботаніка", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Стерня після жнив за два тижні зеленіє сама: те, що впало на землю під час косовиці, сходить.", source: "Хліборобство", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Хата, яку білили щороку заново, за століття має на стіні кількасот шарів вапна, і кожен клала чиясь рука.", source: "Народний побут", theme: .renewal, subtheme: .cutAndComeAgain),

        // MARK: The turning year
        Passage(text: "Гримить! Благодатна пора наступає.", source: "Іван Франко", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Весна красна квітками, а осінь — плодами.", source: "Українське прислів'я", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Веснянки співали не про весну, а до весни: їх заводили в колі, щоб вона почула й прийшла.", source: "Народна пісня", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "На Сорок святих пекли сорок пташок із тіста і роздавали дітям, щоб ті виходили надвір гукати жайворонків.", source: "Народний звичай", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Не я б'ю, верба б'є, за тиждень Великдень.", source: "Народна примовка", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "На Зелені свята хату вбирали клечанням, а долівку встеляли лепехою та м'ятою, і в хаті цілий тиждень пахло лугом.", source: "Народний звичай", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Три Спаси йдуть один за одним — медовий, яблучний і горіховий, — саме в тому порядку, у якому доходить урожай.", source: "Народний календар", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Бабине літо — кілька теплих днів, коли в повітрі летить павутиння: то павучата розселяються, поки ще тихо.", source: "Ентомологія", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Обжинки: останній сніп жали всім гуртом, з нього плели вінок і несли господареві до двору зі співом.", source: "Народний звичай", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Дідух — сніп жита, який на Різдво ставили на покуті. Навесні його обмолочували, і те зерно сіяли першим.", source: "Народний звичай", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Зимове сонцестояння в мові називали сонцеворотом: не кінцем, а поворотом.", source: "Народний календар", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Перший весняний грім вважали знаком, що земля прокинулася; після нього виїжджали орати.", source: "Народна прикмета", theme: .renewal, subtheme: .theTurningYear),

        // MARK: Made whole
        Passage(text: "Я на вбогім сумнім перелозі буду сіять барвисті квітки.", source: "Леся Українка", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Щеплення: живець і підщепа зростаються так, що між ними більше не видно межі, і далі це одне дерево.", source: "Садівництво", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Зламану кістку зростає не лікар. Він тільки складає її так, щоб тіло могло зробити своє.", source: "Медицина", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Кора, здерта з дерева смугою, заростає валиком; на тому місці лишається шрам, товщий і міцніший за здорову кору.", source: "Лісівництво", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Тріснуту макітру стягували дротом, і вона служила далі. Викидати цілу річ через одну тріщину не було заведено.", source: "Народний побут", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Гоїти означає не лікувати, а давати загоюватися: рана заростає сама, а той, хто гоїть, тільки не заважає.", source: "Українська мова", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Ліс після пожежі заростає не тими деревами, що згоріли: спершу приходять берези й осики, а дуб вертається аж через сто років.", source: "Лісівництво", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "У солоні озера Солотвина сто років їздять лікувати легені: тамтешня вода настільки солона, що тримає людину на поверхні.", source: "Географія", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Кожух, перешитий утретє, тепліший за новий, бо кожен, хто його перешивав, знав, де він протирається.", source: "Кушнірство", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Роса змиває з листя пил, і вранці зелень виглядає новішою, ніж була ввечері.", source: "Спостереження", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Розсаду, яка прив'яла після пересадки, не заливають водою: її притінюють на день, і вона підводиться сама.", source: "Городництво", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Криницю чистять раз на кілька років: спускаються вниз, вибирають мул, і за тиждень вода вертається чистіша, ніж була.", source: "Народний побут", theme: .renewal, subtheme: .madeWhole),

        // MARK: - Light

        // MARK: The edges of the day
        Passage(text: "Ніч яка місячна, зоряна, ясная! Видно, хоч голки збирай.", source: "Михайло Старицький", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Світає, смеркає, вечоріє, розвиднюється: пора дня має в мові власні дієслова, і жодному з них не потрібен той, хто діє.", source: "Українська мова", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Досвітки — зимові сходини молоді ще перед світанком. Працювали, співали і розходилися, коли починало сіріти.", source: "Народний звичай", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Зоря в мові — і зірка, і те світло, що стоїть перед сходом сонця; вечірня зоря і ранкова зоря виявилися однією планетою.", source: "Народна астрономія", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "На смерканні заганяли худобу, і це була остання робота дня, яку ще робили видно.", source: "Народний побут", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Найкоротша ніч у році припадає на Купала, і в ту ніч у селі майже не лягали спати.", source: "Народний календар", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Перед грозою повітря стає нерухоме, а світло жовтіє; це помітили задовго до того, як навчилися це пояснювати.", source: "Народна прикмета", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Найдовші тіні бувають не вранці, а тоді, коли сонце вже сідає, і тоді ж вони найм'якші по краях.", source: "Оптика", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Роса випадає не вночі, а під ранок, коли трава вихолола найдужче.", source: "Метеорологія", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Улітку сонце сходить майже на північному сході, а взимку — далеко на південному; за рік точка сходу пробігає добру чверть обрію.", source: "Астрономія", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Синя година настає, коли сонце вже під обрієм, а небо ще світиться. Тіней тоді немає зовсім.", source: "Оптика", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Зірниці — далекі блискавиці без грому, які видно теплими серпневими вечорами: гроза за обрієм, надто далека, щоб її почути.", source: "Метеорологія", theme: .light, subtheme: .theEdgesOfTheDay),

        // MARK: Reading the light
        Passage(text: "Молодий соняшник повертає голову за сонцем від ранку до вечора, а вночі тихо повертається назад на схід.", source: "Ботаніка", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Рослина рахує не світло, а темряву: коли ночі стають довшими за певну міру, вона зацвітає.", source: "Ботаніка", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Кульбаба закривається перед дощем, і по ній видно погоду краще, ніж по небу.", source: "Народна прикмета", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Мати-й-мачуха цвіте раніше, ніж випускає листя: жовті квітки на голій землі беруть світло, поки його ще ніхто не забрав.", source: "Ботаніка", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Барвінок зимує зеленим під снігом і починає працювати на світлі раніше за все інше в лісі.", source: "Ботаніка", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Проліски і ряст встигають відцвісти, поки дуби не розпустилися: увесь їхній рік — це шість тижнів світла на дні лісу.", source: "Ботаніка", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Іван Пулюй робив трубки, що світилися невидимим промінням, і зняв ними знімок людської руки — з кістками наскрізь.", source: "Історія науки", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Крізь зелений лист униз доходить більше зеленого світла, ніж усякого іншого; тому й тінь у лісі зелена.", source: "Оптика", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Місяць уповні світить у сотні тисяч разів слабше за сонце: цього досить, щоб бачити дорогу, і замало, щоб бачити колір.", source: "Астрономія", theme: .light, subtheme: .readingTheLight),
        Passage(text: "На пелюстках багатьох квіток є смуги, помітні тільки в ультрафіолеті. Бджола їх бачить, і вони показують їй, куди сідати.", source: "Ентомологія", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Сніг відбиває майже все світло, яке на нього падає, а зорана земля — майже нічого; тому наприкінці зими поле тане плямами.", source: "Фізика", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Свічку в хаті ставили так, щоб вона світила на руки, а не в очі. Хто вміє прясти, той знає, звідки має падати світло.", source: "Народний побут", theme: .light, subtheme: .readingTheLight),

        // MARK: Light itself
        Passage(text: "Чумацький Шлях назвали так тому, що по тій смузі чумаки правили вози, ідучи вночі по сіль.", source: "Народна астрономія", theme: .light, subtheme: .lightItself),
        Passage(text: "Волосожар і Стожари — два народні імені однієї купки зірок, яку в книжках звуть Плеядами.", source: "Народна астрономія", theme: .light, subtheme: .lightItself),
        Passage(text: "Віз — сім зірок, які ніколи не заходять. За ними в степу знаходили північ і в найтемнішу ніч.", source: "Народна астрономія", theme: .light, subtheme: .lightItself),
        Passage(text: "Світло від сонця йде до нас вісім хвилин. Коли воно доходить, воно вже трохи старе.", source: "Астрономія", theme: .light, subtheme: .lightItself),
        Passage(text: "Сонечко — і мала сонячна пляма, і жучок із чорними цятками. Мова дала їм одне ім'я і не бачить у цьому нічого дивного.", source: "Українська мова", theme: .light, subtheme: .lightItself),
        Passage(text: "Веселка стоїть завжди навпроти сонця, і побачити її можна тільки тоді, коли воно за спиною.", source: "Оптика", theme: .light, subtheme: .lightItself),
        Passage(text: "У народі казали, що веселка одним кінцем п'є воду з річки і носить її в хмару.", source: "Народне вірування", theme: .light, subtheme: .lightItself),
        Passage(text: "Заграва над степом улітку стоїть майже до півночі, бо сонце ходить неглибоко під обрієм.", source: "Астрономія", theme: .light, subtheme: .lightItself),
        Passage(text: "Світло, відбите від води, тремтить на стелі хати. Це та сама хвиля, тільки видима.", source: "Оптика", theme: .light, subtheme: .lightItself),
        Passage(text: "Трухляве дерево в лісі часом світиться вночі холодним зеленим світлом. Світить не воно, а грибниця в ньому.", source: "Мікологія", theme: .light, subtheme: .lightItself),
        Passage(text: "Світляки світять спалахами, і кожен вид має свій лад спалахів, за яким його впізнають свої.", source: "Ентомологія", theme: .light, subtheme: .lightItself),
        Passage(text: "Ясно, ясний, з'ясувати: у мові те, що видно, і те, що зрозуміло, виросло з одного кореня.", source: "Українська мова", theme: .light, subtheme: .lightItself),

        // MARK: - Pattern

        // MARK: Counted
        Passage(text: "Не хвались, ідучи на торг, а хвались, ідучи з торгу.", source: "Українське прислів'я", theme: .pattern, subtheme: .counted),
        Passage(text: "Одна ластівка весни не робить.", source: "Українське прислів'я", theme: .pattern, subtheme: .counted),
        Passage(text: "В українській абетці тридцять три літери, і одна з них, ї, сама по собі цілий склад.", source: "Українська мова", theme: .pattern, subtheme: .counted),
        Passage(text: "В українській мові сім відмінків, і сьомий, кличний, не називає людину, а кличе її.", source: "Українська мова", theme: .pattern, subtheme: .counted),
        Passage(text: "На Святвечір ставлять дванадцять страв і починають із куті — пшениці з медом і маком.", source: "Народний звичай", theme: .pattern, subtheme: .counted),
        Passage(text: "Сорок клинців — писанковий візерунок, поділений на сорок полів, і в кожному полі свій знак.", source: "Народне мистецтво", theme: .pattern, subtheme: .counted),
        Passage(text: "Мірка, гарнець, четверик: зерно колись міряли не вагою, а посудом, і в кожному краї посуд був свій.", source: "Народні міри", theme: .pattern, subtheme: .counted),
        Passage(text: "Насіння в соняшнику лягає двома наборами спіралей: в один бік їх двадцять одна, у другий — тридцять чотири. Далі буде тридцять чотири і п'ятдесят п'ять.", source: "Ботаніка", theme: .pattern, subtheme: .counted),
        Passage(text: "Місяці названі за роботою й погодою: січень січе, березень будить березу, липень цвіте липою, серпень жне серпом.", source: "Українська мова", theme: .pattern, subtheme: .counted),
        Passage(text: "Копа — шістдесят снопів, полукіпок — тридцять. У полі рахували копами, а не снопами, бо снопи ніхто б не долічив.", source: "Народні міри", theme: .pattern, subtheme: .counted),
        Passage(text: "Дні тижня в мові пронумеровані: вівторок другий, четвер четвертий, п'ятниця п'ята.", source: "Українська мова", theme: .pattern, subtheme: .counted),
        Passage(text: "Сім і дев'ять трапляються в казках частіше за всі інші числа: за дев'ятьма горами, на сьомому небі, через сім земель.", source: "Фольклористика", theme: .pattern, subtheme: .counted),

        // MARK: Fitted together
        Passage(text: "Витинанка — візерунок, вирізаний із складеного вдвоє паперу: обидві половини виходять однакові, бо ніж ішов один раз.", source: "Народне мистецтво", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Мережка — шов, у якому нитки з тканини виймають, а те, що лишилося, стягують у пучечки. Дірка стає візерунком.", source: "Вишивання", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Вишивка хрестиком тримається на тому, що всі верхні стібки лежать в один бік; якщо котрийсь ляже інакше, це видно через усю сорочку.", source: "Вишивання", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Стільник у вулику складається з шестикутників, бо на однакову кількість воску так виходить найбільше комірок.", source: "Бджільництво", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Зруб без жодного цвяха тримається на тому, що кожна колода лежить у вирубі попередньої.", source: "Теслярство", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Трипільські поселення будували колами: хати стояли по кільцях одна за одною, а середина лишалася порожня.", source: "Археологія", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Безконечник — писанковий візерунок, лінія без початку й кінця, яку ведуть доти, доки вона не зійдеться сама з собою.", source: "Народне мистецтво", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Плетений тин тримає сам себе: жоден прут не прибитий, кожен просто заведений за наступний.", source: "Народний побут", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Килим ткали від краю до краю, і візерунок мусив зійтися посередині; полічити його треба було ще до першої нитки.", source: "Ткацтво", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Скіфська пектораль із Товстої Могили має три яруси: угорі люди й свійська худоба, посередині квіти, унизу звірі.", source: "Археологія", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Ластів'яче гніздо ліплять грудочками, покладеними рядами. Кожен ряд мусить підсохнути, поки не покладуть наступний.", source: "Орнітологія", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Скирту складають так, щоб кожен наступний сніп притискав попередній; тоді дощ по ній стікає і всередину не заходить.", source: "Хліборобство", theme: .pattern, subtheme: .fittedTogether),

        // MARK: Order named
        Passage(text: "Борис Грінченко склав словник української мови на чотири томи: близько шістдесяти восьми тисяч слів, зібраних із живої мови.", source: "Мовознавство", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Іван Франко зібрав понад тридцять тисяч народних приповідок і розклав їх не за темами, а за словами, з яких вони зроблені.", source: "Фольклористика", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Кличний відмінок має власні закінчення: друг стає друже, мати — мамо, Марія — Маріє. Ним нічого не скажеш про людину, тільки їй.", source: "Українська мова", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Роса, іній, паморозь, ожеледь: те, що осідає з повітря, має в мові стільки імен, скількома способами воно це робить.", source: "Українська мова", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Хуртовина, завірюха, метелиця, хуга: сніг, який летить, названо кількома словами, і кожне про свою силу вітру.", source: "Українська мова", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Пантелеймон Куліш, Іван Пулюй та Іван Нечуй-Левицький разом переклали Біблію українською; повне видання вийшло 1903 року.", source: "Історія книги", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Пересопницьке Євангеліє переписували з 1556 до 1561 року, і писали його так, щоб читалося зрозуміло, а не тільки урочисто.", source: "Історія книги", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Володимир Вернадський, перший президент Академії наук у Києві, показав, що тонкий живий шар планети працює як одне ціле.", source: "Історія науки", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Народний календар не має чисел. Він має Стрітення, Юрія, Покрову і Введення, і кожне з них — не дата, а робота.", source: "Народний календар", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "У вівчаря на полонині кожна вівця має свій карб на вусі, і за тими карбами ввечері розбирають отару назад по господарях.", source: "Полонинське господарство", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Латина називає рослину за родом і виглядом, а народна назва каже, що з нею робити: розхідник, чистотіл, підбіл, звіробій.", source: "Ботаніка", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Мова розрізняє синій і блакитний як два кольори, а не як один світліший за інший.", source: "Українська мова", theme: .pattern, subtheme: .orderNamed),

        // MARK: - Ground

        // MARK: The soil itself
        Passage(text: "Чорнозем — земля, чорна від перегною; його суцільний масив тягнеться степом і лісостепом на сотні кілометрів.", source: "Ґрунтознавство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "У жмені доброї землі живих істот більше, ніж людей на світі.", source: "Ґрунтознавство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Дощовий черв'як пропускає крізь себе землю і лишає її позаду кращою, ніж узяв.", source: "Зоологія", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Гній перегорає в купі сам: усередині буває так гаряче, що взимку з купи йде пара.", source: "Хліборобство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Пісок, глина і мул у різних частках дають різну землю; господар розтирає її пальцями і на дотик знає, що вродить.", source: "Ґрунтознавство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Глина в Опішні жирна і чиста, і саме через неї там уже кілька століть роблять посуд.", source: "Гончарство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Земля під перелогом відпочиває не тому, що порожня, а тому, що в ній заново збирається те, що з неї взяли.", source: "Хліборобство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Горох і люпин лишають після себе землю багатшою: на їхньому корінні сидять бульбочки з бактеріями, які беруть азот просто з повітря.", source: "Ботаніка", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Лес — жовтий пил, який намело вітром за льодовикову добу. Чорнозем виріс на ньому зверху, як шкірка на молоці.", source: "Геологія", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Копнеш на штик — темне, на два — жовте. Товщина того темного і є весь ґрунт, який має поле.", source: "Ґрунтознавство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Солончак білий не від снігу, а від солі, що вийшла нагору з водою і лишилася, коли вода випарувалася.", source: "Ґрунтознавство", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Земля пахне дощем ще перед дощем: волога піднімає з неї те, що суха вона тримала при собі.", source: "Спостереження", theme: .ground, subtheme: .theSoilItself),

        // MARK: A place you are from
        Passage(text: "Стоїть гора високая, попід горою гай, зелений гай, густесенький, неначе справді рай.", source: "Леонід Глібов", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Скрізь добре, а вдома найкраще.", source: "Українське прислів'я", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Кожному мила своя сторона.", source: "Українське прислів'я", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Своя хата — своя правда, своя стріха — своя втіха.", source: "Українське прислів'я", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Дома і стіни помагають.", source: "Українське прислів'я", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Іван був дев'ятнадцятою дитиною в гуцульській родині Палійчуків.", source: "Михайло Коцюбинський, Тіні забутих предків", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Назви сіл кажуть, де вони стоять: Заріччя за річкою, Підгайці під гаєм, Криничне при криниці.", source: "Топоніміка", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Піч у хаті і гріла, і годувала, і на ній спали. Хату будували навколо неї, а не її вставляли в хату.", source: "Народний побут", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Призьба — глиняний виступ уздовж стіни хати. Вона гріє стіну знизу, а надвечір гріє тих, хто на ній сидить.", source: "Народний побут", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Хату білили перед святами, а внизу пускали кольорову підводку, щоб не було видно, куди зі стріхи хлюпає дощ.", source: "Народний побут", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Криниця з журавлем стояла на вигоні, і біля неї сходилося пів села, бо по воду ходили всі.", source: "Народний побут", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Левада — низина при воді з вербами й травою, якої не орють, бо вона щовесни стоїть під водою.", source: "Географія", theme: .ground, subtheme: .aPlaceYouAreFrom),

        // MARK: A kept place
        Passage(text: "Асканія-Нова існує з 1898 року, і в ній збереглася ділянка справжнього цілинного степу.", source: "Заповідна справа", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Сад коло хати садили не на продаж: по одному дереву кожного сорту, аби від липня до жовтня щось та й доходило.", source: "Садівництво", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Полонина — гірський луг, на який улітку виганяють худобу. Вона нічия і водночас усіх, хто на неї жене.", source: "Полонинське господарство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Пасіка стоїть на одному місці десятиліттями, бо бджола вертається не у свій вулик, а на своє місце.", source: "Бджільництво", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Гілки, якими на Зелені свята вбирали хату, потім сушили і не викидали абияк.", source: "Народний звичай", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Тік — рівний утоптаний майданчик, де молотили. Його підмазували глиною щоліта, щоб зерно не губилося в тріщинах.", source: "Хліборобство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Огорожа в селі показувала не власність, а те, куди не можна худобі; ворота для людей лишали відчинені.", source: "Народний побут", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Софія Київська стоїть із одинадцятого століття, і на її стінах збереглося кілька тисяч написів, залишених тими, хто заходив.", source: "Історія", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Дуба, що ріс на межі двох полів, не рубали: під ним відпочивали ті, хто орав по обидва боки.", source: "Народний звичай", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Сіно береже той, хто вміє класти стіг: погано складений мокне зверху, добре складений сохне зсередини.", source: "Хліборобство", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Городина в старому городі стояла завжди на тих самих грядках, і кожні три роки грядки міняли місцями.", source: "Городництво", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Кременецький ботанічний сад заклали на початку дев'ятнадцятого століття, і частина його дерев старша за всіх, хто там ходить.", source: "Заповідна справа", theme: .ground, subtheme: .aKeptPlace),

        // MARK: - Travel

        // MARK: How a seed goes
        Passage(text: "Перекотиполе відламується від власного кореня, коли достигне, і котиться степом, розсіваючи насіння по дорозі.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Ковила має остюк, що скручується й розкручується від вологи; так насінина сама вкручується в землю.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Реп'ях чіпляється гачечками до всього, що пройшло повз; із нього придумали застібку, яка тримає на тому самому.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Кульбаба летить на парасольці з волосинок і сідає тим далі, чим сухіше повітря; у вологу вона парасольку складає.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Клен і явір кидають насінину з крилом, і вона падає обертаючись; обертання вповільнює падіння і дає вітру час.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Омела не падає на землю зовсім: птах витирає липке насіння об гілку, і воно проростає там, де його витерли.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Насіння латаття плаває в слизовій оболонці кілька днів, доки та не розкисне, і аж тоді тоне — там, куди його віднесло.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Вільха роняє насіння просто на воду: у нього є повітряні кишеньки, і воно пливе, доки не зачепиться за берег.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Череда чіпляється до коров'ячого боку і їде з чередою до самого вечора, а злазить уже в іншому кінці села.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Горобина проходить крізь дрозда неушкодженою і сходить потім краще, ніж якби впала просто під дерево.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Дощовик стріляє спорами, коли на нього впаде крапля: удар видавлює сіру хмарку через дірочку вгорі.", source: "Мікологія", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Найлегше насіння у світі — в орхідей: мільйон насінин важить менше за грам, і вітер несе їх, як пилюку.", source: "Ботаніка", theme: .travel, subtheme: .howASeedGoes),

        // MARK: The road
        Passage(text: "Язик до Києва доведе.", source: "Українське прислів'я", theme: .travel, subtheme: .theRoad),
        Passage(text: "Не спитавши броду, не сунься у воду.", source: "Українське прислів'я", theme: .travel, subtheme: .theRoad),
        Passage(text: "Чумаки їздили по сіль волами, бо віл іде повільно, зате не пристає і вертається з тим самим возом.", source: "Історія", theme: .travel, subtheme: .theRoad),
        Passage(text: "Гостинець — старе слово і для великої дороги, і для того подарунка, який із тієї дороги привозять додому.", source: "Українська мова", theme: .travel, subtheme: .theRoad),
        Passage(text: "Плай — стежка в горах, протоптана вівцями. Вона ніколи не йде найкоротше, зате завжди йде найлегше.", source: "Гуцульська говірка", theme: .travel, subtheme: .theRoad),
        Passage(text: "Шлях, дорога, стежка, путівець, битий шлях: у мові дороги розрізняють за тим, скільки по них ходило.", source: "Українська мова", theme: .travel, subtheme: .theRoad),
        Passage(text: "Чумацька валка ставала табором щовечора там, де була вода, і за водою розписувався весь маршрут наперед.", source: "Історія", theme: .travel, subtheme: .theRoad),
        Passage(text: "Дніпро тече з півночі на південь через усю рівнину і колись був не перепоною, а головною дорогою.", source: "Географія", theme: .travel, subtheme: .theRoad),
        Passage(text: "Перевіз і брід — два способи перейти річку, і обидва означали, що там, де вони є, з часом стане село.", source: "Географія", theme: .travel, subtheme: .theRoad),
        Passage(text: "Дорогу в степу правили по курганах: їх видно за кілька верст, і вони не рухаються.", source: "Історія", theme: .travel, subtheme: .theRoad),
        Passage(text: "Кобзарі ходили від села до села і за ночівлю не платили: їх годували за пісню, а дорога в них не кінчалася.", source: "Історія музики", theme: .travel, subtheme: .theRoad),
        Passage(text: "Мандрувати і блукати — не те саме: мандрівник знає, куди йде, і просто не поспішає туди дійти.", source: "Українська мова", theme: .travel, subtheme: .theRoad),

        // MARK: Far off
        Passage(text: "Книги — морська глибина: хто в них пірне аж до дна, той, хоч і труду мав досить, дивнії перли виносить.", source: "Іван Франко", theme: .travel, subtheme: .farOff),
        Passage(text: "Хотіла б я піснею стати у сюю хвилину ясну.", source: "Леся Українка", theme: .travel, subtheme: .farOff),
        Passage(text: "Вирій — теплий край, куди відлітають птахи. У мові він не має ні координат, ні кордону, тільки напрямок.", source: "Українська мова", theme: .travel, subtheme: .farOff),
        Passage(text: "Обрій, виднокруг, небокрай — три слова для однієї лінії, до якої не можна дійти.", source: "Українська мова", theme: .travel, subtheme: .farOff),
        Passage(text: "Лелека з нашого комина зимує південніше екватора і навесні вертається на той самий комин.", source: "Орнітологія", theme: .travel, subtheme: .farOff),
        Passage(text: "Ластівка за життя пролітає стільки, що вистачило б кілька разів обійти землю по колу.", source: "Орнітологія", theme: .travel, subtheme: .farOff),
        Passage(text: "Соловейко, який співає в травні у садку, узимку сидить десь у савані на іншому континенті.", source: "Орнітологія", theme: .travel, subtheme: .farOff),
        Passage(text: "Чумацький Шлях, який видно з подвір'я, — то наша галактика збоку. Ми дивимося на неї зсередини.", source: "Астрономія", theme: .travel, subtheme: .farOff),
        Passage(text: "Юрій Дрогобич надрукував книжку в Римі 1483 року — першу друковану книжку автора з українських земель.", source: "Історія книги", theme: .travel, subtheme: .farOff),
        Passage(text: "Світ за очі — вираз для відстані, якої не міряють. Іти світ за очі означає йти туди, куди дивишся.", source: "Українська мова", theme: .travel, subtheme: .farOff),
        Passage(text: "У рівному степу обрій відходить на кілька десятків кілометрів, і людину там видно задовго до того, як її чути.", source: "Географія", theme: .travel, subtheme: .farOff),
        Passage(text: "Журавлі йдуть на південь клином, і той, хто спереду, весь час міняється, бо йому найважче.", source: "Орнітологія", theme: .travel, subtheme: .farOff),

        // MARK: - Meeting

        // MARK: The moment
        Passage(text: "Стрітення — назва свята, яка означає зустріч. Кажуть, що того дня зима стрічається з літом і вони сперечаються.", source: "Народний календар", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Зустрітися по суті не має однини: зустрічається завжди хтось із кимось, і поодинці цього дієслова не буває.", source: "Українська мова", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Гість на поріг — щастя в дім.", source: "Українське прислів'я", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Перше слово, яке кажуть, зайшовши в чужу хату, — не про себе: питають про здоров'я тих, хто в ній.", source: "Народний звичай", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Дві річки, злившись, довго течуть поруч в одному руслі, не змішуючись: межу між водами видно ще кілька кілометрів.", source: "Гідрологія", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Щеплення береться за кілька тижнів, але все вирішується в перші години, поки обидва зрізи ще вологі.", source: "Садівництво", theme: .meeting, subtheme: .theMoment),
        Passage(text: "На вечорниці сходилися з кількох кутків села. Хату наймали в удови, і за те носили їй дрова.", source: "Народний звичай", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Перелаз — місце в тину, через яке ходять до сусіда. Його роблять нижчим спеціально.", source: "Народний побут", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Бджола і квітка бачаться кілька секунд, і за ці секунди робиться те, заради чого цвіла ціла яблуня.", source: "Ботаніка", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Дві гілки, які роками труться одна об одну, стирають кору і зростаються. Далі вони живуть як одна.", source: "Лісівництво", theme: .meeting, subtheme: .theMoment),
        Passage(text: "На толоку сходилися вдосвіта, і хто прийшов найперший, той розкладав вогонь під казаном.", source: "Народний звичай", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Купальську ніч зустрічали біля води і пускали вінки за течією: хтось на тому березі мав їх виловити.", source: "Народний звичай", theme: .meeting, subtheme: .theMoment),

        // MARK: Two that need each other
        Passage(text: "Орхідея не проросте без гриба, а гриб бере від неї цукор. Ні те, ні те окремо в лісі не живе.", source: "Ботаніка", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Лишайник — це гриб і водорість, які живуть як одне ціле; окремо їх у природі майже не знайти.", source: "Ботаніка", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Червона конюшина не зав'яжеться без джмеля: у неї глибокий віночок, і дістати до дна може тільки довгий хоботок.", source: "Ентомологія", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Бульбочкові бактерії на корінні гороху беруть азот із повітря і віддають рослині, а рослина за це годує їх цукром.", source: "Ботаніка", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Лелека годується на скошених луках, а луки викошують люди. Там, де перестали косити, лелека не селиться.", source: "Орнітологія", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Волошка росте разом із житом рівно стільки, скільки люди сіють жито; поза полем вона майже не трапляється.", source: "Ботаніка", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Пару волів у ярмі не розлучають: двоє звикають до кроку одне одного і з третім уже не йдуть.", source: "Хліборобство", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Мікориза — сплетіння грибниці з корінням дерева. Майже кожне дерево в лісі живе в такій спілці і без неї росте гірше.", source: "Мікологія", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Пилок сосни летить за вітром, і сосна не вибирає, з ким їй зійтися; тому жодні дві сосни в лісі не однакові.", source: "Ботаніка", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Дуб і сойка одне без одного обходяться погано: дуб не має як пересунутися, а сойка не має чого ховати на зиму.", source: "Орнітологія", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Дерева, зрослі корінням, роками годують пеньок зрубаного сусіда, і той стоїть живий, хоч і без жодної гілки.", source: "Лісівництво", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Є дієслова, які без другої людини не працюють: миритися, вітатися, знайомитися, домовлятися. Усі вони на -ся.", source: "Українська мова", theme: .meeting, subtheme: .twoThatNeedEachOther),

        // MARK: The manners of it
        Passage(text: "Не красна хата кутами, а красна пирогами.", source: "Українське прислів'я", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Чим багаті, тим і раді.", source: "Українське прислів'я", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Без хліба — суха бесіда.", source: "Українське прислів'я", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Гостя саджали на покуті — у найсвітліший куток хати, спиною до двох стін, лицем до всіх, хто заходить.", source: "Народний звичай", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Хліб і сіль подають на рушнику: хліб — щоб було з чим, сіль — щоб було чим присмачити, рушник — щоб не з голих рук.", source: "Народний звичай", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Ласкаво просимо — не наказ і не дозвіл, а прохання: господар просить гостя зробити йому ласку і зайти.", source: "Українська мова", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Добродію — старе звертання до незнайомого. Воно означає того, хто робить добро, і його казали наперед.", source: "Українська мова", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Будьмо — тост, у якому нема ні побажання, ні прохання. Тільки дієслово бути в першій особі множини.", source: "Українська мова", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "На толоці не платили грішми: годували обідом, виставляли вечерю, і за рік той самий гурт обходив усі двори.", source: "Народний звичай", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Гостя не питали, чи він голодний: ставили на стіл і сідали разом, бо питання поставило б його в незручне.", source: "Народний звичай", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Здоровенькі були — привітання, яке бажає не радості й не успіху, а здоров'я, і бажає його в минулому часі.", source: "Українська мова", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Через поріг не вітаються і нічого не передають: спершу заходять у хату, а тоді вже подають руку.", source: "Народний звичай", theme: .meeting, subtheme: .theMannersOfIt),

        // MARK: - Kinship

        // MARK: Grown together
        Passage(text: "Толока — робота гуртом: сусіди сходяться поставити комусь хату або зібрати комусь урожай, і черга обходить усіх.", source: "Народний звичай", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Громада — великий чоловік.", source: "Українське прислів'я", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Де згода, там і сила.", source: "Українське прислів'я", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Людина без роду, як дерево без коріння.", source: "Українське прислів'я", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Побратимство: двоє чужих ставали братами через обряд, і рід визнавав це за справжню спорідненість.", source: "Етнографія", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Кум і кума — не кровна рідня, а рідня, яку вибрали; хрещені батьки входили в родину назавжди.", source: "Етнографія", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Осиковий гай часто буває одним деревом: стовбури окремі, коріння спільне, і восени вони жовтіють усі одного дня.", source: "Ботаніка", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Дві яблуні, щеплені з однієї гілки, родять однакові яблука, хоч ростуть за сто кілометрів одна від одної.", source: "Садівництво", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Гриби стають колом тому, що грибниця росте від однієї точки рівно на всі боки. Коло щороку більшає.", source: "Мікологія", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Вулик узимку — одне тіло: бджоли в клубі міняються місцями, бо з краю холодніше, і жодна не стоїть там довго.", source: "Бджільництво", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "На весілля хату прибирали гуртом, і кожна сусідка приносила щось своє — рушник, миску, глек.", source: "Народний звичай", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Сірий журавель танцює в парі, і пара тримається роками. Танцюють вони і тоді, коли давно вже разом.", source: "Орнітологія", theme: .kinship, subtheme: .grownTogether),

        // MARK: The words for it
        Passage(text: "Рід, родина, народ, урожай, природа: усе це виросло з одного кореня — родити.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Ненька, матінка, матуся, мамця: пестливих форм для матері в мові стільки, що на кожну не вистачає окремого приводу.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Зменшене слово в українській мові не завжди означає мале: сонечком звуть і сонце, і дитину, і жучка на долоні.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Свояк, дівер, зовиця, ятрівка, сват: спорідненість через шлюб має в мові стільки імен, скільки в хаті кутів.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Батько, тато, неньо, дєдьо: у різних краях батька звуть по-різному, і в кожному краї це слово найтепліше.", source: "Діалектологія", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "У горах хрещеного батька звуть нанашком, і в родині це слово важить не менше за дядька.", source: "Діалектологія", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Стрийко — брат батька, вуйко — брат матері. Мова розрізняє, з якого боку прийшла рідня.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Земляк — той, хто з тієї самої землі. Слово рахує не кров, а місце, і цього виявляється досить.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Свій означає і власний, і рідний, і того, кого не треба пояснювати.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Пестливі імена будуються сходинками: Марія, Марійка, Маруся, Марусенька, і кожна сходинка ближча за попередню.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Онук, правнук, праправнук, пращур: рахунок родини вперед і назад ведуть тим самим складом пра-.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Вітатися — дієслово взаємне. Сам із собою не привітаєшся, і той, хто вітається, уже не сам.", source: "Українська мова", theme: .kinship, subtheme: .theWordsForIt),

        // MARK: Two people
        Passage(text: "Сім'я вечеря коло хати, вечірня зіронька встає.", source: "Тарас Шевченко, Кобзар", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Де згода в сімействі, де мир і тишина, щасливі там люди, блаженна сторона.", source: "Іван Котляревський, Наталка Полтавка", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Світ не без добрих людей.", source: "Українське прислів'я", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Одна бджола мало меду наносить.", source: "Українське прислів'я", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "На весіллі молодим зв'язують руки рушником, і розв'язують уже тоді, коли вони вийшли з-за столу.", source: "Народний звичай", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Двоє в човні гребуть у різні боки, і саме через це човен іде прямо.", source: "Спостереження", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Лелеки живуть парою, а прилітають нарізно: перший вертається самець і кілька днів чекає на гнізді.", source: "Орнітологія", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Двоє, які довго живуть разом, починають ходити в один крок, самі того не помічаючи.", source: "Спостереження", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Косарі йдуть у покіс уступом, один за одним, і темп усім задає той, хто попереду.", source: "Хліборобство", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "У парі волів є свій правий і свій лівий, і поміняти їх місцями не можна: обидва підуть гірше.", source: "Хліборобство", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Пилка-дворучка ходить тільки тоді, коли обидва тягнуть до себе і жоден не штовхає.", source: "Теслярство", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Вівчарі на полонині сплять по двоє під одним ліжником, бо вночі там холодно навіть у липні.", source: "Полонинське господарство", theme: .kinship, subtheme: .twoPeople),

        // MARK: - Peace

        // MARK: Quiet as a sound
        Passage(text: "Затихло все, тілько дівчата та соловейко не затих.", source: "Тарас Шевченко, Кобзар", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Шелест, шурхіт, шемрання, шепіт: тихі звуки в мові починаються майже всі з одного шиплячого.", source: "Українська мова", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Бриніти кажуть про струну, якої вже не чути, але вона ще тремтить; так само бринить дріт на морозі.", source: "Українська мова", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Гомін — звук багатьох голосів разом, у якому жодного не розібрати. Гомонить і ліс, і базар, і вода на перекаті.", source: "Українська мова", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Луна означає відлуння. Щоб почути її окремо від власного голосу, до стіни має бути щонайменше сімнадцять метрів.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Трембіту чути за кілька кілометрів, хоч вона й не гучна: довга труба дає низький звук, а низький звук іде далі.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Тиша дзвенить не в повітрі, а у вусі: коли навколо немає нічого, чути власну кров.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Свіжий сніг поглинає звук, і після снігопаду в селі тихіше, ніж будь-коли за цілий рік.", source: "Акустика", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Сова летить нечутно, бо край її махового пера не рівний, а гребінчастий, і повітря на ньому не свистить.", source: "Орнітологія", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Клекіт лелеки — не голос: голосу в нього майже немає, він стукає дзьобом, закинувши голову на спину.", source: "Орнітологія", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Цвіркун сюрчить тим частіше, чим тепліше; полічивши сюрчання за хвилину, можна вгадати температуру.", source: "Ентомологія", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Тиха вода греблі рве.", source: "Українське прислів'я", theme: .peace, subtheme: .quietAsASound),

        // MARK: The words for stopping
        Passage(text: "Годі означає і досить, і більше не треба. Ним кінчають і роботу, і суперечку, і не пояснюють нічого.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Утихомирити складено з тиші й миру: щоб щось утихомирити, у мові треба зробити його і тихим, і мирним.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Перемир'я стоїть між: пере- і мир, час, у який уже не воюють, але ще не помирилися.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Миритися — дієслово на -ся, і без другої людини воно не працює: помиритися можна тільки з кимось.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Мирова — стара сільська угода, якою кінчали сварку між сусідами при свідках, і по ній сварку більше не згадували.", source: "Етнографія", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Спочинок і покій — з одного кореня. Покоями в старому домі звали кімнати, тобто місця, де спочивають.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Край означає і берег, і кінець, і сторону. Сказати немає краю — це сказати, що воно триває.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Гамувати означає стишувати, і угамувати можна і біль, і вогонь, і голод, і дитину.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Пора й честь знати кажуть гість і господар про одну й ту саму хвилину, і кожен каже це з приязню.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Косарі кінчали покіс не за годинником, а за росою: коли трава ставала мокра, коса переставала брати.", source: "Хліборобство", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Спочивати кажуть і про людину, і про землю: поле спочиває під перелогом так само, як людина в неділю.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Затишшя — коротка тиша серед негоди. Вітер спадає, і за цей час на морі встигають зайти в затоку.", source: "Українська мова", theme: .peace, subtheme: .theWordsForStopping),

        // MARK: At ease
        Passage(text: "Садок вишневий коло хати, хрущі над вишнями гудуть.", source: "Тарас Шевченко, Кобзар", theme: .peace, subtheme: .atEase),
        Passage(text: "Село! і серце одпочине.", source: "Тарас Шевченко, Кобзар", theme: .peace, subtheme: .atEase),
        Passage(text: "Світ ловив мене, та не спіймав.", source: "Григорій Сковорода (1722–1794)", theme: .peace, subtheme: .atEase),
        Passage(text: "Хіба ревуть воли, як ясла повні?", source: "Українське прислів'я", theme: .peace, subtheme: .atEase),
        Passage(text: "Затишок — місце, куди не дістає вітер. Слово зроблене з тиші, хоч ідеться в ньому про тепло.", source: "Українська мова", theme: .peace, subtheme: .atEase),
        Passage(text: "Призьба нагрівається за день і віддає тепло аж до ночі; тому надвечір сидять на ній, а не в хаті.", source: "Народний побут", theme: .peace, subtheme: .atEase),
        Passage(text: "Полудень у жнива — година, коли не жнуть: лягають у холодок під возом і сплять, поки не спаде спека.", source: "Хліборобство", theme: .peace, subtheme: .atEase),
        Passage(text: "Кіт муркоче десь на двадцяти п'яти коливаннях за секунду і робить це і на вдиху, і на видиху.", source: "Зоологія", theme: .peace, subtheme: .atEase),
        Passage(text: "Кожух, накинутий на плечі надвечір, гріє краще, ніж одягнений: між ним і спиною лишається повітря.", source: "Народний побут", theme: .peace, subtheme: .atEase),
        Passage(text: "Чай із чебрецю й материнки пахне сильніше, коли його не кип'ятити, а залити окропом і накрити.", source: "Народна медицина", theme: .peace, subtheme: .atEase),
        Passage(text: "Неділя в селі була не порожнім днем, а днем, у який не робили того, що можна відкласти.", source: "Народний побут", theme: .peace, subtheme: .atEase),
        Passage(text: "Спека спадає не тоді, коли сонце сідає, а годиною пізніше: земля віддає тепло довше, ніж світить сонце.", source: "Метеорологія", theme: .peace, subtheme: .atEase)
    ]
}
